const items = $input.all();
const out = [];
for (const item of items) {
  const it = item.json;
  const rules = '(none yet)';        // learning loop (Fetch Context) fills these later
  const examples = '(none yet)';
  const routeSystem =
    "You are an Executive Assistant triaging and handling one email for your principal. " +
    "Decide ONE route, then act. Output STRICT JSON only - no prose, no fences:\n" +
    "{ \"route\": \"reply|review|task|fyi|ignore\", \"summary\": \"<=12 words\", " +
    "\"reply_subject\": \"\", \"reply_body\": \"\", \"task_title\": \"\", " +
    "\"due_date\": \"YYYY-MM-DD or empty\", \"why\": \"\" }\n" +
    "Routes: reply = a straightforward response you can draft; review = needs a human " +
    "decision (proposal, contract, money, commitments); task = a to-do that is not an " +
    "email; fyi = no action; ignore = not actually actionable.\n" +
    "Drafting: match the sender register, be concise, use ONLY facts in the email - " +
    "never invent commitments, dates, numbers, or names. You DRAFT/PROPOSE only; a human sends.\n" +
    "Standing rules (obey these):\n" + rules;
  const routeUser =
    "From: " + (it.from_addr || '') + "\nSubject: " + (it.subject || '') + "\n\n" +
    (it.body || '') + "\n\n--- How the principal has replied to this sender before ---\n" + examples;
  out.push({ json: Object.assign({}, it, { routeSystem: routeSystem, routeUser: routeUser }) });
}
return out;

const src = $('Build Route Prompt').all();
const all = $input.all();
const out = [];
for (let i = 0; i < all.length; i++) {
  const o = src[i] ? src[i].json : {};
  const resp = all[i] ? all[i].json : {};
  let text = '';
  try { text = resp.content[0].text; } catch (e) {}
  let d = { route: 'fyi', summary: o.subject || '' };
  if (text) {
    const m = text.replace(/```json|```/g, '').match(/\{[\s\S]*\}/);
    if (m) { try { d = JSON.parse(m[0]); } catch (e) {} }
  }
  const route = (d.route || 'fyi').toLowerCase();
  const base = { id: o.id, account: o.account, priority: o.priority,
                 summary: d.summary || '', source_message_id: o.message_id || '' };
  if (route === 'reply') {
    out.push({ json: Object.assign({}, base, {
      target: 'ea_actions', reply_body: d.reply_body || '',
      payload: { to: [o.from_addr], subject: d.reply_subject || ('Re: ' + (o.subject || '')),
                 body: d.reply_body || '', in_reply_to: o.message_id || null },
      dedup_key: 'reply:' + (o.message_id || o.id) }) });
  } else if (route === 'review') {
    out.push({ json: Object.assign({}, base, {
      target: 'attention', title: o.subject || 'Needs review', why: d.why || '',
      dedup_key: 'review:' + (o.message_id || o.id) }) });
  } else if (route === 'task') {
    out.push({ json: Object.assign({}, base, {
      target: 'tasks', task_title: d.task_title || (o.subject || 'Follow up'),
      due_date: d.due_date || null }) });
  } else {
    out.push({ json: Object.assign({}, base, { target: 'none' }) });
  }
}
return out;
